// Run one training scenario as a SPAWNED child while the parent stays async
// (spawn + await exit), so the parent's fake gateway can answer. This is the
// corrected harness shape that replaces spawnSync in the pipeline check.
// Usage: node scripts/run-scenario.mjs <configJsonFile>
// The scenario script path + env come from the config file; parent prints
// the child's stdout at the end. All scenario JS is generated by the caller
// (training-pipeline.check.mjs) and passed by path.
import { spawn } from "node:child_process";
import fs from "node:fs";

const cfg = JSON.parse(fs.readFileSync(process.argv[2], "utf8"));
const gw = cfg.gateway ? (await import(cfg.gateway)).default : null; // parent-side fake gw module (optional)

const child = spawn(process.execPath, [cfg.script], {
  env: { ...process.env, ...cfg.env },
  stdio: ["ignore", "inherit", "inherit"],
});
const code = await new Promise((resolve) => child.on("close", resolve));
if (gw && typeof gw.close === "function") gw.close();
process.exit(code);
